window.__Q=window.__Q||{};Object.assign(window.__Q,{"e2059112-1019-48a4-a70a-3b33e18211ca":{"st":"<p><figure class=\"image\"><svg height=\"456.84\" viewbox=\"0 0 380 456.84\" width=\"380\" xmlns=\"http://www.w3.org/2000/svg\"><g data-name=\"Layer 1\" id=\"ed420550-79eb-48d4-af01-cd27cdd08afd\"><defs>\n<marker id=\"marker0\" markerheight=\"6\" markerunits=\"strokeWidth\" markerwidth=\"6\" refx=\"3\" refy=\"3\">\n<polygon fill=\"#000\" points=\"3 0, 0 5.196, 6 5.196\"></polygon>\n</marker>\n<marker id=\"marker1\" markerheight=\"5\" markerunits=\"strokeWidth\" markerwidth=\"5\" refx=\"2.5\" refy=\"2.5\">\n<path d=\"M0,0 L0,5 L5,5 L5,0 z\" fill=\"#BBB\" stroke=\"#000\" stroke-width=\"1.5\"></path>\n</marker>\n<marker id=\"marker2\" markerheight=\"6\" markerunits=\"strokeWidth\" markerwidth=\"6\" refx=\"3\" refy=\"3\">\n<circle cx=\"3\" cy=\"3\" fill=\"#FFF\" r=\"1.8\" stroke=\"#000\" stroke-width=\".6\"></circle>\n</marker>\n<marker id=\"marker3\" markerheight=\"6\" markerunits=\"strokeWidth\" markerwidth=\"6\" refx=\"3\" refy=\"3\">\n<polygon fill=\"#999\" points=\"0.5 3, 2.3 2.3, 3 0.5, 3.7 2.3, 5.5 3, 3.7 3.7, 3 5.5, 2.3 3.7, 0.5 3\" stroke=\"#000\" stroke-linejoin=\"round\" stroke-width=\".5\"></polygon>\n</marker>\n</defs><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"113.83999633789062\" x2=\"365\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"72\" y2=\"72\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"107.83999633789062\" x2=\"119.83999633789062\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"72\" y2=\"72\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(101.83999633789062 78)\">400</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"113.83999633789062\" x2=\"365\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"122\" y2=\"122\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"107.83999633789062\" x2=\"119.83999633789062\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"122\" y2=\"122\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(101.83999633789062 128)\">300</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"113.83999633789062\" x2=\"365\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"172\" y2=\"172\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"107.83999633789062\" x2=\"119.83999633789062\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"172\" y2=\"172\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(101.83999633789062 178)\">200</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"113.83999633789062\" x2=\"365\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"222\" y2=\"222\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"107.83999633789062\" x2=\"119.83999633789062\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"222\" y2=\"222\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(101.83999633789062 228)\">100</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"113.83999633789062\" x2=\"365\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"272\" y2=\"272\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"107.83999633789062\" x2=\"119.83999633789062\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"272\" y2=\"272\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(101.83999633789062 278)\">0</text><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"middle\" transform=\"translate(24 172) rotate(-90)\">Yearly copper production </text><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"middle\" transform=\"translate(48 172) rotate(-90)\">(in millions of pounds)</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"113.83999633789062\" x2=\"113.83999633789062\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"72\" y2=\"272\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"155.6999969482422\" x2=\"155.6999969482422\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"72\" y2=\"272\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"middle\" transform=\"translate(155.6999969482422 291.84)\" x=\"0\" xmlns=\"http://www.w3.org/2000/svg\" y=\"0\">1889</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"239.4199981689453\" x2=\"239.4199981689453\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"72\" y2=\"272\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"middle\" transform=\"translate(239.4199981689453 291.84)\" x=\"0\" xmlns=\"http://www.w3.org/2000/svg\" y=\"0\">1902</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"323.13999938964844\" x2=\"323.13999938964844\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"72\" y2=\"272\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"middle\" transform=\"translate(323.13999938964844 291.84)\" x=\"0\" xmlns=\"http://www.w3.org/2000/svg\" y=\"0\">1909</text><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"middle\" transform=\"translate(239.4199981689453 24)\">Copper Production for </text><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"middle\" transform=\"translate(239.4199981689453 48)\">Three States, 1889-1909</text><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"middle\" transform=\"translate(239.4199981689453 325.67999999999995)\">Year</text><rect fill=\"none\" height=\"103\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\" width=\"159.11712646484375\" x=\"117.94143676757812\" xmlns=\"http://www.w3.org/2000/svg\" y=\"342.84000000000003\"></rect><line marker-end=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"124.94143676757812\" x2=\"151.94143676757812\" y1=\"359.84000000000003\" y2=\"359.84000000000003\"></line><line marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"151.94143676757812\" x2=\"178.94143676757812\" y1=\"359.84000000000003\" y2=\"359.84000000000003\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"top\" transform=\"translate(188.94143676757812 366.84000000000003)\"> Montana</text><line marker-end=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"124.94143676757812\" x2=\"151.94143676757812\" y1=\"391.84000000000003\" y2=\"391.84000000000003\"></line><line marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"151.94143676757812\" x2=\"178.94143676757812\" y1=\"391.84000000000003\" y2=\"391.84000000000003\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"top\" transform=\"translate(188.94143676757812 398.84000000000003)\"> Arizona</text><line marker-end=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"124.94143676757812\" x2=\"151.94143676757812\" y1=\"423.84000000000003\" y2=\"423.84000000000003\"></line><line marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"151.94143676757812\" x2=\"178.94143676757812\" y1=\"423.84000000000003\" y2=\"423.84000000000003\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"top\" transform=\"translate(188.94143676757812 430.84000000000003)\"> Michigan</text><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"155.6999969482422\" x2=\"239.4199981689453\" y1=\"220\" y2=\"139\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"155.6999969482422\" x2=\"239.4199981689453\" y1=\"256\" y2=\"212.5\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"155.6999969482422\" x2=\"239.4199981689453\" y1=\"228.5\" y2=\"187\"></line><line marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\" stroke=\"#000\" stroke-width=\"2.4\" x1=\"239.4199981689453\" x2=\"323.13999938964844\" y1=\"139\" y2=\"115\"></line><line marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\" stroke=\"#000\" stroke-dasharray=\"9 6\" stroke-width=\"2.4\" x1=\"239.4199981689453\" x2=\"323.13999938964844\" y1=\"212.5\" y2=\"126.5\"></line><line marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\" stroke=\"#000\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"239.4199981689453\" x2=\"323.13999938964844\" y1=\"187\" y2=\"156.5\"></line></g></svg></figure></p>\n<p>Copper had been mined in the US for thousands of years, but large-scale commercial mining of copper took off starting in the late 1800s. This was due to several factors. Technological advancements in the mining industry led to improvements in the production of copper. This helped the country keep up with the growing number of people wanting to buy copper starting in the 1890s. At the same time, the growth of the railroad system made the transportation of copper in large batches much easier. Several states saw rapid growth in the production of this resource, for example: <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","r":"<p>Choice D is the best answer. The text asks us to provide examples of several states that saw rapid growth in copper production from the 1890s onward. The graph depicts Arizona, Michigan, and Montana all experiencing such rapid growth during this time period.</p><p>Choice A is incorrect. The claim is about states experiencing rapid growth in copper production. This statement only discusses one state and does not provide evidence of rapid growth&mdash;in fact, it discusses a slow-down of growth. Choice B is incorrect. The claim is about states experiencing rapid growth in copper production, and this statement provides a comparison of production rates between states, rather than an example of rapid growth. Choice C is incorrect. The claim is about several states experiencing rapid growth in copper production. This statement only discusses one state and does not provide evidence of growth in copper production.</p>","a":"D","o":["<p>The rise in copper production in Michigan slowed from 1902 to 1909.</p>","<p>Montana and Arizona produced more copper than Michigan did in 1909.</p>","<p>Fewer than 100 million pounds of copper were produced in Arizona in 1889.</p>","<p>Copper production rose significantly from 1889 to 1909 for Arizona, Michigan, and Montana.</p>"],"q":"<p>Which choice most effectively uses the data in the graph to complete the example?</p>","tp":"mcq"},"e223b909-79a8-46de-a366-14993592a4c7":{"q":"<p style=\"text-align: center;\"><math alttext=\"x equals 8\"><mrow>\n\t<mi>x</mi>\n\t<mo>=</mo>\n\t<mn>8</mn>\n</mrow>\n</math></p>\n<p style=\"text-align: center;\"><math alttext=\"y equals x squared plus 8\"><mrow>\n\t<mi>y</mi>\n\t<mo>=</mo>\n\t<mrow>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>2</mn>\n\t\t</msup>\n\t\t<mo>+</mo>\n\t\t<mn>8</mn>\n\t</mrow>\n</mrow>\n</math></p>\n<p style=\"text-align: left;\">The graphs of the equations in the given system of equations intersect at the point <math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math> in the <em>xy</em>-plane. What is the value of <math alttext=\"y\"><mi>y</mi>\n</math>?</p>","o":["<p><math alttext=\"8\"><mn>8</mn>\n</math></p>","<p><math alttext=\"24\"><mn>24</mn>\n</math></p>","<p><math alttext=\"64\"><mn>64</mn>\n</math></p>","<p><math alttext=\"72\"><mn>72</mn>\n</math></p>"],"a":"D","tp":"mcq","st":"","r":"<p>Choice D is correct. Since the graphs of the equations in the given system intersect at the point <math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math>, the point <math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math>&nbsp;represents a solution to the given system of equations. The first equation of the given system of equations states that <math alttext=\"x equals 8\"><mrow>\n\t<mi>x</mi>\n\t<mo>=</mo>\n\t<mn>8</mn>\n</mrow>\n</math>. Substituting <math alttext=\"8\"><mn>8</mn>\n</math> for <math alttext=\"x\"><mi>x</mi>\n</math> in the second equation of the given system of equations yields <math alttext=\"y equals 8 squared plus 8\"><mi>y</mi><mo>=</mo><msup><mn>8</mn><mn>2</mn></msup><mo>+</mo><mn>8</mn></math>, or <math alttext=\"y equals 72\"><mrow>\n\t<mi>y</mi>\n\t<mo>=</mo>\n\t<mn>72</mn>\n</mrow>\n</math>. Therefore, the value of <math alttext=\"y\"><mi>y</mi>\n</math> is <math alttext=\"72\"><mn>72</mn>\n</math>.</p>\n<p>Choice A is incorrect. This is the value of <math alttext=\"x\"><mi>x</mi>\n</math>, not <math alttext=\"y\"><mi>y</mi>\n</math>.</p>\n<p>Choice B is incorrect and may result from conceptual or calculation errors.</p>\n<p>Choice C is incorrect and may result from conceptual or calculation errors.</p>"},"e2330828-1418-4ad0-8880-e2467492c024":{"r":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the ancient Inca farming method. In this context, &ldquo;effective&rdquo; means successful in producing a desired result. The text describes how the Inca used terraces with built-in irrigation systems to grow crops at different altitudes and then indicates that this farming method produced positive results &ldquo;as evidenced by the great number and variety of crops grown at that time.&rdquo; The context clearly suggests that the terraced farming approach was highly productive, or effective.</p><p>Choice A is incorrect because to describe the Inca farming method as &ldquo;chaotic&rdquo; contradicts the text&rsquo;s description of a systematic approach using deliberately constructed terraces with built-in irrigation systems. Moreover, the &ldquo;great number and variety of crops&rdquo; yielded by this method seems unlikely to result from a disorganized, or chaotic, approach. Choice B is incorrect because &ldquo;uniform&rdquo; means consistent or the same throughout. It does not make sense in this context to describe a farming method as highly uniform if it produced a &ldquo;great number and variety of crops.&rdquo; Moreover, the text indicates that Inca terrace farming was specifically designed to accommodate different crops at different altitudes, highlighting the diversity rather than uniformity of this approach. Choice D is incorrect because the success of the method, &ldquo;as evidenced by the great number and variety of crops grown,&rdquo; does not support the claim that the Inca farming method was &ldquo;burdensome,&rdquo; or difficult to implement or maintain. In fact, the context clearly emphasizes the advantages, rather than the burdens, of Inca terrace farming.</p>","st":"<p>Ancient Inca inhabiting the Andes Mountains used terraces, rows of flattened land with built-in irrigation systems, to grow crops at different altitudes. This method of farming proved to be highly <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>, as evidenced by the great number and variety of crops grown at that time.</p>","tp":"mcq","a":"C","o":["<p>chaotic</p>","<p>uniform</p>","<p>effective</p>","<p>burdensome</p>"],"q":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>"},"e2375cf4-517a-4d38-94ef-5c6c3cc7b879":{"r":"<p style=\"text-align: left;\">Choice B is correct. Since <math alttext=\"x cubed\"><msup>\n\t<mi>x</mi>\n\t<mn>3</mn>\n</msup>\n</math> is a common factor of each term in the given expression, the expression can be rewritten as&nbsp;<math alttext=\"x cubed left parenthesis 5 x squared minus 6 x plus 8 right parenthesis\"><msup><mi>x</mi><mn>3</mn></msup><mfenced><mrow><mn>5</mn><msup><mi>x</mi><mn>2</mn></msup><mo>-</mo><mn>6</mn><mi>x</mi><mo>+</mo><mn>8</mn></mrow></mfenced></math>.</p>\n<p style=\"text-align: left;\">Choice A is incorrect. This expression is equivalent to <math alttext=\"5 x Superscript 5 minus 6 x Superscript 4\"><mrow>\n\t<mrow>\n\t\t<mn>5</mn>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>5</mn>\n\t\t</msup>\n\t</mrow>\n\t<mo>-</mo>\n\t<mrow>\n\t\t<mn>6</mn>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>4</mn>\n\t\t</msup>\n\t</mrow>\n</mrow>\n</math>.</p>\n<p style=\"text-align: left;\">Choice C is incorrect. This expression is equivalent to <math alttext=\"40 x Superscript 5 minus 48 x Superscript 4 plus 8 x cubed\"><mrow>\n\t<mrow>\n\t\t<mn>40</mn>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>5</mn>\n\t\t</msup>\n\t</mrow>\n\t<mo>-</mo>\n\t<mrow>\n\t\t<mn>48</mn>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>4</mn>\n\t\t</msup>\n\t</mrow>\n\t<mo>+</mo>\n\t<mrow>\n\t\t<mn>8</mn>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>3</mn>\n\t\t</msup>\n\t</mrow>\n</mrow>\n</math>.</p>\n<p style=\"text-align: left;\">Choice D is incorrect. This expression is equivalent to <math alttext=\"minus 36 x Superscript 9 plus 48 x Superscript 8 plus 6 x Superscript 5\"><mrow>\n\t<mrow>\n\t\t<mo>-</mo>\n\t\t<mn>36</mn>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>9</mn>\n\t\t</msup>\n\t</mrow>\n\t<mo>+</mo>\n\t<mrow>\n\t\t<mn>48</mn>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>8</mn>\n\t\t</msup>\n\t</mrow>\n\t<mo>+</mo>\n\t<mrow>\n\t\t<mn>6</mn>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>5</mn>\n\t\t</msup>\n\t</mrow>\n</mrow>\n</math>.</p>","st":"","tp":"mcq","a":"B","o":["<p><math alttext=\"x Superscript 4 Baseline left parenthesis 5 x minus 6 right parenthesis\"><mrow>\n\t<msup>\n\t\t<mi>x</mi>\n\t\t<mn>4</mn>\n\t</msup>\n\t<mfenced>\n\t\t<mrow>\n\t\t\t<mrow>\n\t\t\t\t<mn>5</mn>\n\t\t\t\t<mi>x</mi>\n\t\t\t</mrow>\n\t\t\t<mo>-</mo>\n\t\t\t<mn>6</mn>\n\t\t</mrow>\n\t</mfenced>\n</mrow>\n</math></p>","<p><math alttext=\"x cubed left parenthesis 5 x squared minus 6 x plus 8 right parenthesis\"><mrow>\n\t<msup>\n\t\t<mi>x</mi>\n\t\t<mn>3</mn>\n\t</msup>\n\t<mfenced>\n\t\t<mrow>\n\t\t\t<mrow>\n\t\t\t\t<mn>5</mn>\n\t\t\t\t<msup>\n\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t<mn>2</mn>\n\t\t\t\t</msup>\n\t\t\t</mrow>\n\t\t\t<mo>-</mo>\n\t\t\t<mrow>\n\t\t\t\t<mn>6</mn>\n\t\t\t\t<mi>x</mi>\n\t\t\t</mrow>\n\t\t\t<mo>+</mo>\n\t\t\t<mn>8</mn>\n\t\t</mrow>\n\t</mfenced>\n</mrow>\n</math></p>","<p><math alttext=\"8 x cubed left parenthesis 5 x squared minus 6 x plus 1 right parenthesis\"><mrow>\n\t<mn>8</mn>\n\t<msup>\n\t\t<mi>x</mi>\n\t\t<mn>3</mn>\n\t</msup>\n\t<mfenced>\n\t\t<mrow>\n\t\t\t<mrow>\n\t\t\t\t<mn>5</mn>\n\t\t\t\t<msup>\n\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t<mn>2</mn>\n\t\t\t\t</msup>\n\t\t\t</mrow>\n\t\t\t<mo>-</mo>\n\t\t\t<mrow>\n\t\t\t\t<mn>6</mn>\n\t\t\t\t<mi>x</mi>\n\t\t\t</mrow>\n\t\t\t<mo>+</mo>\n\t\t\t<mn>1</mn>\n\t\t</mrow>\n\t</mfenced>\n</mrow>\n</math></p>","<p><math alttext=\"6 x Superscript 5 Baseline left parenthesis minus 6 x Superscript 4 Baseline plus 8 x cubed plus 1 right parenthesis\"><mrow>\n\t<mn>6</mn>\n\t<msup>\n\t\t<mi>x</mi>\n\t\t<mn>5</mn>\n\t</msup>\n\t<mfenced>\n\t\t<mrow>\n\t\t\t<mrow>\n\t\t\t\t<mo>-</mo>\n\t\t\t\t<mn>6</mn>\n\t\t\t\t<msup>\n\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t<mn>4</mn>\n\t\t\t\t</msup>\n\t\t\t</mrow>\n\t\t\t<mo>+</mo>\n\t\t\t<mrow>\n\t\t\t\t<mn>8</mn>\n\t\t\t\t<msup>\n\t\t\t\t\t<mi>x</mi>\n\t\t\t\t\t<mn>3</mn>\n\t\t\t\t</msup>\n\t\t\t</mrow>\n\t\t\t<mo>+</mo>\n\t\t\t<mn>1</mn>\n\t\t</mrow>\n\t</mfenced>\n</mrow>\n</math></p>"],"q":"<p style=\"text-align: left;\">Which expression is equivalent to <math alttext=\"5 x Superscript 5 minus 6 x Superscript 4 plus 8 x cubed\"><mrow>\n\t<mrow>\n\t\t<mn>5</mn>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>5</mn>\n\t\t</msup>\n\t</mrow>\n\t<mo>-</mo>\n\t<mrow>\n\t\t<mn>6</mn>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>4</mn>\n\t\t</msup>\n\t</mrow>\n\t<mo>+</mo>\n\t<mrow>\n\t\t<mn>8</mn>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>3</mn>\n\t\t</msup>\n\t</mrow>\n</mrow>\n</math>?</p>"},"e24d7288-d58e-49e9-92dc-1ba13221b2e3":{"st":"<p>&ldquo;The Mountain&rdquo; is a 1914 poem by Robert Frost. In the poem, the speaker visits a town next to a mountain. The speaker claims to feel protected by the mountain, saying <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","r":"<p>Choice C is the best answer because it most effectively uses a quotation from \"The Mountain\" to illustrate the claim that the speaker feels protected by the mountain. In the quotation, the speaker recounts that the mountain felt like a wall that offers shelter from the wind. That the speaker felt sheltered by the mountain suggests that it offered the speaker a sense of being protected.</p><p>Choice A is incorrect because this quotation doesn&rsquo;t express the speaker&rsquo;s feeling of being protected by the mountain. Instead, it notes that the speaker has seen a dry ravine and a pasture. Choice B is incorrect because this quotation doesn&rsquo;t express the speaker&rsquo;s feeling of being protected by the mountain. Instead, it simply states that there is a mountain, which is meant to be viewed. Choice D is incorrect because this quotation doesn&rsquo;t express the speaker&rsquo;s feeling of being protected by the mountain. Instead, it indicates that the speaker has gone around the mountain.</p>","q":"<p>Which quotation from &ldquo;The Mountain&rdquo; most effectively illustrates the claim?</p>","o":["<p>&ldquo;A dry ravine emerged under boughs / Into the pasture.&rdquo;</p>","<p>&ldquo;The mountain stood there to be pointed at.&rdquo;</p>","<p>&ldquo;I felt it like a wall / Behind which I was sheltered from a wind.&rdquo;</p>","<p>&ldquo;I crossed the river and swung round the mountain.&rdquo;</p>"],"a":"C","tp":"mcq"},"e2565394-6b89-4d8e-8b02-06a363d8a20f":{"tp":"spr","q":"<p style=\"text-align: left;\">A distance of <math alttext=\"61\"><mn>61</mn>\n</math> furlongs is equivalent to how many feet? <math alttext=\"left parenthesis 1 furlong  equals 220 yards and 1 yard  equals 3 feet right parenthesis\"><mfenced><mrow><mn>1</mn><mo>&#160;</mo><mtext>furlong</mtext><mo>=</mo><mn>220</mn><mo>&#160;</mo><mtext>yards</mtext><mo>&#160;</mo><mtext>and</mtext><mo>&#160;</mo><mn>1</mn><mo>&#160;</mo><mtext>yard</mtext><mo>=</mo><mn>3</mn><mo>&#160;</mo><mtext>feet</mtext></mrow></mfenced></math></p>","o":[],"a":"40260","r":"<p style=\"text-align: left;\">The correct answer is <math alttext=\"40,260\"><mn>40,260</mn>\n</math>. It's given that&nbsp;<math alttext=\"1 furlong  equals 220 yards\"><mn>1</mn><mo>&#160;</mo><mtext>furlong</mtext><mo>=</mo><mn>220</mn><mo>&#160;</mo><mtext>yards</mtext></math> and&nbsp;<math alttext=\"1 yard  equals 3 feet\"><mn>1</mn><mo>&#160;</mo><mtext>yard</mtext><mo>=</mo><mn>3</mn><mo>&#160;</mo><mtext>feet</mtext></math>. It follows that a distance of <math alttext=\"61\"><mn>61</mn>\n</math> furlongs is equivalent to&nbsp;<math alttext=\"left parenthesis 61 furlongs right parenthesis left parenthesis StartFraction 220 yards Over 1 furlong EndFraction right parenthesis left parenthesis StartFraction 3 feet Over 1 yard EndFraction right parenthesis\"><mfenced><mrow><mn>61</mn><mo>&#160;</mo><mtext>furlongs</mtext></mrow></mfenced><mfenced><mfrac><mrow><mn>220</mn><mo>&#160;</mo><mtext>yards</mtext></mrow><mrow><mn>1</mn><mo>&#160;</mo><mtext>furlong</mtext></mrow></mfrac></mfenced><mfenced><mfrac><mrow><mn>3</mn><mo>&#160;</mo><mtext>feet</mtext></mrow><mrow><mn>1</mn><mo>&#160;</mo><mtext>yard</mtext></mrow></mfrac></mfenced></math>,&nbsp;or <math alttext=\"40,260\"><mn>40,260</mn>\n</math> feet.</p>","st":""},"e2571e58-9647-4c76-bee1-1ffb191506d2":{"r":"<p>Choice D is the best answer. The convention being tested is pronoun-antecedent agreement. The singular pronoun \"he\" agrees in number with the singular antecedent \"F&eacute;lix Gonz&aacute;lez-Torres,\" and it clearly indicates that Gonz&aacute;lez-Torres created the additional installations.</p><p>Choice A is incorrect because the plural noun phrase \"they all\" doesn&rsquo;t agree in number with the singular antecedent \"F&eacute;lix Gonz&aacute;lez-Torres,\" and it doesn&rsquo;t clearly indicate that he (Gonz&aacute;lez-Torres) created the additional installations. Choice B is incorrect because the plural pronoun \"those\" doesn&rsquo;t agree in number with the singular antecedent \"F&eacute;lix Gonz&aacute;lez-Torres,\" and it doesn&rsquo;t clearly indicate that he (Gonz&aacute;lez-Torres) created the additional installations. Choice C is incorrect because the plural pronoun \"both\" doesn&rsquo;t agree in number with the singular antecedent \"F&eacute;lix Gonz&aacute;lez-Torres,\" and it doesn&rsquo;t clearly indicate that he (Gonz&aacute;lez-Torres) created the additional installations.</p>","st":"<p>F&eacute;lix Gonz&aacute;lez-Torres debuted his sculpture <em>&ldquo;Untitled&rdquo; (USA Today)</em> in New York City in 1990. The work consists of piled candy, a material Gonz&aacute;lez-Torres became known for. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> created additional installations using a variety of sweets, like bubblegum, lollipops, and chocolates.</p>","tp":"mcq","q":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","a":"D","o":["<p>They all</p>","<p>Those</p>","<p>Both</p>","<p>He</p>"]},"e257f385-1988-4616-9742-5ef7a832d1db":{"r":"<p>Choice C is the best answer. The first sentence tells us that video meetings are &ldquo;less conducive to&rdquo; (meaning less good for) brainstorming. This suggests that the video meeting participants&rsquo; focus is bad for their creativity. &ldquo;Impede&rdquo; means &ldquo;delay&rdquo; or &ldquo;prevent,&rdquo; which works perfectly in this context. </p><p>Choice A is incorrect. This choice is too positive to fit the context. The first sentence tells us that video meetings are &ldquo;less conducive to&rdquo; (meaning less good for) brainstorming. This suggests that the video meeting participants&rsquo; focus is bad for their creativity. Choice B is incorrect. This choice doesn&rsquo;t make sense. The participants&rsquo; intense focus on the screen is the subject of the missing verb. It wouldn&rsquo;t make sense to say that their over-focusing &ldquo;criticizes&rdquo; their creativity. Choice D is incorrect. &ldquo;Construct&rdquo; means &ldquo;build&rdquo; or &ldquo;make,&rdquo; which is too positive to fit the context. The first sentence tells us that video meetings are &ldquo;less conducive to&rdquo; (meaning less good for) brainstorming. This suggests that the video meeting participants&rsquo; focus is bad for their creativity. </p>","st":"<p>Business researcher Melanie Brucks and colleagues found that remote video conference meetings may be less conducive to brainstorming than in-person meetings are. The researchers suspect that video meeting participants are focused on staring at the speaker on the screen and don&rsquo;t allow their eyes or mind to wander as much, which may ultimately <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> creativity.</p>","tp":"mcq","q":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","a":"C","o":["<p>recommend</p>","<p>criticize</p>","<p>impede</p>","<p>construct</p>"]},"e27fbdf6-d244-477f-91b5-804e24e6bf28":{"q":"<p>The student wants to describe the distinctive style of Houser&rsquo;s sculptures. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","a":"B","o":["<p>A sculptor, illustrator, and painter, Houser developed a distinctive style for portraying Native American figures.</p>","<p>Houser&rsquo;s sculptures employ abstract, modernist forms to depict Native American figures.</p>","<p>Many other artists have been influenced by the style of Houser&rsquo;s sculptures.</p>","<p>The sculpture <em>Sacred Rain Arrow</em> is a well-known example of Houser&rsquo;s style.</p>"],"tp":"mcq","st":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Allan Houser was a Chiricahua Warm Springs Apache sculptor, illustrator, and painter.</li>\n<li>Many of his sculptures featured Native American figures.</li>\n<li>He depicted this subject matter using abstract, modernist forms, developing a distinctive style that influenced many other artists.</li>\n<li>His well-known sculpture <em>Sacred Rain Arrow</em> was pictured on the State of Oklahoma license plate.</li>\n</ul>","r":"<p>Choice B is the best answer. The sentence describes the distinctive style of Houser&rsquo;s sculptures, explaining that the sculptures use abstract, modernist forms to depict Native American figures. </p><p>Choice A is incorrect. While the sentence indicates that Houser developed a distinctive style for portraying Native American figures, it doesn&rsquo;t describe this style. Choice C is incorrect. While the sentence states that other artists have been influenced by the style of Houser&rsquo;s sculptures, it doesn&rsquo;t describe this style. Choice D is incorrect. While the sentence mentions the name of a sculpture that&rsquo;s a well-known example of Houser&rsquo;s style, it doesn&rsquo;t describe the sculpture&rsquo;s style. </p>"},"e29c0a06-1d44-4568-9459-7f708ecebbca":{"r":"<p>Choice D is the best answer. The sentence emphasizes a difference between surface-dwelling and cave-dwelling tetras, noting that while surface-dwelling tetras can see, cave-dwelling tetras can&rsquo;t. </p><p>Choice A is incorrect. While the sentence notes that surface-dwelling and cave-dwelling tetras are different, it doesn&rsquo;t emphasize any difference between the two populations of tetras. Choice B is incorrect because the sentence explains that cave-dwelling tetras use sensory receptors on their skulls to navigate; it doesn&rsquo;t emphasize a difference between surface-dwelling and cave-dwelling tetras. Choice C is incorrect. While the sentence notes that there are two different populations of Mexican tetras, it doesn&rsquo;t emphasize any difference between the two populations. </p>","st":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Mexican tetras are a fish species with two distinct populations.</li>\n<li>Surface-dwelling tetras live on the surface and are able to see.</li>\n<li>Cave-dwelling tetras live in total darkness and have lost the ability to see.</li>\n<li>Cave-dwelling tetras have asymmetrical skulls with more sensory receptors on one side than the other.</li>\n<li>These receptors help cave-dwelling tetras navigate in darkness.</li>\n</ul>","tp":"mcq","a":"D","o":["<p>Surface-dwelling and cave-dwelling tetras may belong to the same species, but they are quite different.</p>","<p>Cave-dwelling tetras can no longer see but use sensory receptors on their skulls to navigate.</p>","<p>Mexican tetras are a fish species with two distinct populations: surface-dwelling tetras and cave-dwelling tetras.</p>","<p>Surface-dwelling tetras can see, whereas cave-dwelling tetras cannot.</p>"],"q":"<p>The student wants to emphasize a difference between surface-dwelling and cave-dwelling tetras. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>"},"e2a04a2f-1b77-450f-8d40-6adb9294ce88":{"r":"<p>Choice D is the best answer. The sentence describes how scientific understanding of the glass&rsquo;s origin has evolved, explaining that new research suggests the glass formed as a result of a cometary explosion instead of being caused by grass fires (as was previously believed).</p><p>Choice A is incorrect. The sentence explains the conclusion of the older study; it doesn&rsquo;t describe how scientific understanding of the glass&rsquo;s origin has evolved. Choice B is incorrect. While the sentence indicates that the two studies provided different explanations, it doesn&rsquo;t describe how scientific understanding of the glass&rsquo;s origin has evolved. Choice C is incorrect. The sentence references a recent finding but doesn&rsquo;t effectively describe how scientific understanding of the glass&rsquo;s origin has evolved.</p>","st":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Scientists have long sought to determine the origin of glass in Chile&rsquo;s Atacama Desert.</li>\n<li>A 2017 study concluded that ancient grass fires had melted the area&rsquo;s sandy soil into glass.</li>\n<li>In 2021, a different study revealed that the mineral signatures of glass samples were consistent with the mineral signatures of comet samples collected by NASA.</li>\n<li>That study concluded that the glass had formed as a result of a cometary explosion close to the desert&rsquo;s surface.</li>\n</ul>","tp":"mcq","o":["<p>Scientists have long sought to determine the origin of the glass, with one study concluding that it formed when ancient grass fires melted the area&rsquo;s sandy soil.</p>","<p>Studies in 2017 and 2021 offered different explanations for the origin of the glass.&nbsp;</p>","<p>Mineral signatures of glass samples are consistent with those of comet samples collected by NASA, according to new research.</p>","<p>A 2017 study concluded that ancient grass fires had caused the glass&rsquo;s formation, but new research suggests that the glass formed as a result of a cometary explosion close to the desert&rsquo;s surface.</p>"],"a":"D","q":"<p>The student wants to describe how scientific understanding about the glass&rsquo;s origin has evolved. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>"},"e2acc363-d0b7-4b19-ac43-34982f030a3d":{"q":"<p style=\"text-align: left;\">Each side of a <math alttext=\"30\"><mn>30</mn>\n</math>-sided polygon has one of three lengths. The number of sides with length <math alttext=\"8 centimeters left parenthesis cm right parenthesis\"><mrow><mn>8</mn></mrow><mo>&#160;</mo><mtext>centimeters</mtext><mo>&#160;</mo><mfenced><mtext>cm</mtext></mfenced></math> is <math alttext=\"5\"><mn>5</mn>\n</math> times the number of sides <math alttext=\"n\"><mi>n</mi>\n</math> with length <math alttext=\"3 cm\"><mrow><mn>3</mn></mrow><mo>&#160;</mo><mtext>cm</mtext></math>. There are <math alttext=\"6\"><mn>6</mn>\n</math> sides with length <math alttext=\"4 cm\"><mrow><mn>4</mn></mrow><mo>&#160;</mo><mtext>cm</mtext></math>. Which equation must be true for the value of <math alttext=\"n\"><mi>n</mi>\n</math>?</p>","o":["<p><math alttext=\"5 n plus 6 equals 30\"><mrow>\n\t<mrow>\n\t\t<mrow>\n\t\t\t<mn>5</mn>\n\t\t\t<mi>n</mi>\n\t\t</mrow>\n\t\t<mo>+</mo>\n\t\t<mn>6</mn>\n\t</mrow>\n\t<mo>=</mo>\n\t<mn>30</mn>\n</mrow>\n</math></p>","<p><math alttext=\"6 n plus 6 equals 30\"><mrow>\n\t<mrow>\n\t\t<mrow>\n\t\t\t<mn>6</mn>\n\t\t\t<mi>n</mi>\n\t\t</mrow>\n\t\t<mo>+</mo>\n\t\t<mn>6</mn>\n\t</mrow>\n\t<mo>=</mo>\n\t<mn>30</mn>\n</mrow>\n</math></p>","<p><math alttext=\"8 n plus 3 n plus 4 n equals 30\"><mrow><mn>8</mn></mrow><mi>n</mi><mo>+</mo><mrow><mn>3</mn></mrow><mi>n</mi><mo>+</mo><mrow><mn>4</mn></mrow><mi>n</mi><mo>=</mo><mn>30</mn></math></p>","<p><math alttext=\"8 left parenthesis 5 n right parenthesis plus 3 n plus 4 left parenthesis 6 right parenthesis equals 30\"><mrow><mn>8</mn></mrow><mfenced><mrow><mrow><mn>5</mn></mrow><mi>n</mi></mrow></mfenced><mo>+</mo><mrow><mn>3</mn></mrow><mi>n</mi><mo>+</mo><mrow><mn>4</mn></mrow><mfenced><mrow><mn>6</mn></mrow></mfenced><mo>=</mo><mn>30</mn></math></p>"],"a":"B","tp":"mcq","st":"","r":"<p style=\"text-align: left;\">Choice B is correct. It&rsquo;s given that each side of a <math alttext=\"30\"><mn>30</mn>\n</math>-sided polygon has one of three lengths. It's also given that the number of sides with length <math alttext=\"8\"><mn>8</mn>\n</math> <math alttext=\"centimeters left parenthesis cm right parenthesis\"><mtext>centimeters</mtext><mo>&#160;</mo><mfenced><mtext>cm</mtext></mfenced></math> is <math alttext=\"5\"><mn>5</mn>\n</math> times the number of sides <math alttext=\"n\"><mi>n</mi>\n</math> with length <math alttext=\"3 cm\"><mn>3</mn><mo>&#160;</mo><mtext>cm</mtext></math>. Therefore, there are <math alttext=\"5 times n\"><mn>5</mn><mo>&#215;</mo><mi>n</mi></math>, or <math alttext=\"5 n\"><mrow>\n\t<mn>5</mn>\n\t<mi>n</mi>\n</mrow>\n</math>, sides with length <math alttext=\"8 cm\"><mn>8</mn><mo>&#160;</mo><mtext>cm</mtext></math>. It&rsquo;s also given that there are <math alttext=\"6\"><mn>6</mn>\n</math> sides with length <math alttext=\"4 cm\"><mn>4</mn><mo>&#160;</mo><mtext>cm</mtext></math>. Therefore, the number of <math alttext=\"3 cm\"><mn>3</mn><mo>&#160;</mo><mtext>cm</mtext></math>, <math alttext=\"4 cm\"><mn>4</mn><mo>&#160;</mo><mtext>cm</mtext></math>, and&nbsp;<math alttext=\"8 cm\"><mn>8</mn><mo>&#160;</mo><mtext>cm</mtext></math> sides are <math alttext=\"n\"><mi>n</mi>\n</math>, <math alttext=\"6\"><mn>6</mn>\n</math>, and <math alttext=\"5 n\"><mrow>\n\t<mn>5</mn>\n\t<mi>n</mi>\n</mrow>\n</math>, respectively. Since there are a total of <math alttext=\"30\"><mn>30</mn>\n</math> sides, the equation <math alttext=\"n plus 6 plus 5 n equals 30\"><mi>n</mi><mo>+</mo><mn>6</mn><mo>+</mo><mn>5</mn><mi>n</mi><mo>=</mo><mn>30</mn></math> represents this situation. Combining like terms on the left-hand side of this equation yields <math alttext=\"6 n plus 6 equals 30\"><mn>6</mn><mi>n</mi><mo>+</mo><mn>6</mn><mo>=</mo><mn>30</mn></math>. Therefore, the equation that must be true for the value of <math alttext=\"n\"><mi>n</mi>\n</math> is&nbsp;<math alttext=\"6 n plus 6 equals 30\"><mn>6</mn><mi>n</mi><mo>+</mo><mn>6</mn><mo>=</mo><mn>30</mn></math>.</p>\n<p style=\"text-align: left;\">Choice A is incorrect and may result from conceptual or calculation errors.</p>\n<p style=\"text-align: left;\">Choice C is incorrect and may result from conceptual or calculation errors.</p>\n<p style=\"text-align: left;\">Choice D is incorrect and may result from conceptual or calculation errors.</p>"},"e2d7ae77-37f4-4262-93cd-474e4f073caf":{"st":"<p><span role=\"heading\" aria-level=\"2\"><strong>Text 1</strong></span></p>\n<p>A team led by Bernardo Strassburg has found that rewilding farmland (returning the land to its natural state) could help preserve biodiversity and offset carbon emissions. The amount of farmland that would need to be restored, they found, is remarkably low. Rewilding a mere 15% of the world&rsquo;s current farmland would prevent 60% of expected species extinctions and help absorb nearly 299 gigatons of carbon dioxide&mdash;a clear win in the fight against the biodiversity and climate crises.</p>\n<p>&nbsp;</p>\n<p><span role=\"heading\" aria-level=\"2\"><strong>Text 2</strong></span></p>\n<p>While Strassburg&rsquo;s team&rsquo;s findings certainly offer encouraging insight into the potential benefits of rewilding, it&rsquo;s important to consider potential effects on global food supplies. The researchers suggest that to compensate for the loss of food-producing land, remaining farmland would need to produce even more food. Thus, policies focused on rewilding farmland must also address strategies for higher-yield farming.</p>","r":"<p>Choice A is the best answer. Text 1 is extremely positive about Strassburg&rsquo;s team&rsquo;s findings, calling the potential results \"a clear win in the fight against the biodiversity and climate crises.\" Text 2 is not as positive, arguing that while the findings point to \"potential benefits,\" we also need to consider the \"potential effects on global food supplies.\"</p><p>Choice B is incorrect. This isn&rsquo;t a difference between the two views. Text 1 does present the 15% number as enough to achieve meaningful results, but that&rsquo;s not what Text 2 takes issue with: rather, Text 2 argues that we need to consider the effect that rewilding this much farmland would have on food supplies. Choice C is incorrect. This isn&rsquo;t a difference between the two views. Neither text mentions the timeline for achieving the results described by Strassburg&rsquo;s team. Choice D is incorrect. This isn&rsquo;t a difference between the two views. Text 1 focuses on rewilding&rsquo;s effects on both carbon emissions and biodiversity. Text 2 doesn&rsquo;t focus on rewilding&rsquo;s effect on carbon emissions at all. Instead, it focuses on a third factor: global food supplies.</p>","o":["<p>The author of Text 2 approaches the study&rsquo;s findings with some caution, whereas the author of Text 1 is optimistic about the reported potential environmental benefits.</p>","<p>The author of Text 2 claims that the percentage of farmland identified by Strassburg&rsquo;s team is too low for rewilding to achieve meaningful results, whereas the author of Text 1 thinks the percentage is sufficient.</p>","<p>The author of Text 2 believes that the results described by Strassburg&rsquo;s team are achievable in the near future, whereas the author of Text 1 argues that they likely aren&rsquo;t.</p>","<p>The author of Text 2 focuses on rewilding&rsquo;s effect on carbon emissions, whereas the author of Text 1 focuses on its effect on biodiversity.</p>"],"a":"A","q":"<p>Which choice best describes a difference in how the author of Text 1 and the author of Text 2 view Strassburg&rsquo;s team&rsquo;s study?</p>","tp":"mcq"},"e2e5fe90-eac5-48a3-a466-f4a6ead5776e":{"tp":"spr","o":[],"a":"73920","q":"<p style=\"text-align: left;\">A distance of <math alttext=\"112\"><mn>112</mn>\n</math> furlongs is equivalent to how many feet? <math alttext=\"left parenthesis 1 furlong  equals 220 yards and 1 yard  equals 3 feet right parenthesis\"><mfenced><mrow><mn>1</mn><mo>&#160;</mo><mtext>furlong</mtext><mo>=</mo><mn>220</mn><mo>&#160;</mo><mtext>yards</mtext><mo>&#160;</mo><mtext>and</mtext><mo>&#160;</mo><mn>1</mn><mo>&#160;</mo><mtext>yard</mtext><mo>=</mo><mn>3</mn><mo>&#160;</mo><mtext>feet</mtext></mrow></mfenced></math></p>","r":"<p style=\"text-align: left;\">The correct answer is <math alttext=\"73,920\"><mn>73,920</mn>\n</math>. It's given that <math alttext=\"1 furlong  equals 220 yards\"><mn>1</mn><mo>&#160;</mo><mtext>furlong</mtext><mo>=</mo><mn>220</mn><mo>&#160;</mo><mtext>yards</mtext></math> and&nbsp;<math alttext=\"1 yard  equals 3 feet\"><mn>1</mn><mo>&#160;</mo><mtext>yard</mtext><mo>=</mo><mn>3</mn><mo>&#160;</mo><mtext>feet</mtext></math>. It follows that a distance of <math alttext=\"112\"><mn>112</mn></math> furlongs&nbsp;is equivalent to <math alttext=\"left parenthesis 112 furlongs right parenthesis left parenthesis StartFraction 220 yards Over 1 furlong EndFraction right parenthesis left parenthesis StartFraction 3 feet Over 1 yard EndFraction right parenthesis\"><mfenced><mrow><mn>112</mn><mo>&#160;</mo><mtext>furlongs</mtext></mrow></mfenced><mfenced><mfrac><mrow><mn>220</mn><mo>&#160;</mo><mtext>yards</mtext></mrow><mrow><mn>1</mn><mo>&#160;</mo><mtext>furlong</mtext></mrow></mfrac></mfenced><mfenced><mfrac><mrow><mn>3</mn><mo>&#160;</mo><mtext>feet</mtext></mrow><mrow><mn>1</mn><mo>&#160;</mo><mtext>yard</mtext></mrow></mfrac></mfenced></math>, or <math alttext=\"73,920\"><mn>73,920</mn></math> feet.</p>","st":""},"e2f7c1f1-940b-4949-92d5-fb17fa14b93a":{"st":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Hina Hanta is an online archive curated by the Choctaw Nation of Oklahoma.</li>\n<li>Hina Hanta means &ldquo;bright path&rdquo; in Choctaw.</li>\n<li>It features images of cultural artifacts relevant to the history of the Choctaw people.</li>\n<li>It includes a fanner basket (<span lang=\"cho\"><em>ufko tapushik</em></span> in Choctaw) made from cane.</li>\n<li>It includes a robe (<span lang=\"cho\"><em>nita anchi</em></span>) made from bear fur.</li>\n</ul>","r":"<p>Choice B is the best answer. The sentence specifies the fanner basket&rsquo;s name in Choctaw, noting that it&rsquo;s called <span lang=\"cho\"><em>ufko tapushik</em></span>.</p><p>Choice A is incorrect. While the sentence mentions the fanner basket, it doesn&rsquo;t specify its name in Choctaw. Choice C is incorrect. While the sentence mentions the fanner basket, it doesn&rsquo;t specify its name in Choctaw. Choice D is incorrect. The sentence doesn&rsquo;t mention the fanner basket or specify its name in Choctaw.</p>","o":["<p>The Hina Hanta archive features cultural artifacts, such as a fanner basket and a robe, that are relevant to the history of the Choctaw people.</p>","<p>The cane fanner basket, which is included in the Hina Hanta online archive, is called an <span lang=\"cho\"><em>ufko tapushik</em></span>&nbsp;in Choctaw.</p>","<p>Hina Hanta, which means &ldquo;bright path&rdquo; in Choctaw, includes a fanner basket in its archive.</p>","<p>The name of the online archive Hina Hanta means &ldquo;bright path&rdquo; in Choctaw.</p>"],"a":"B","q":"<p>The student wants to specify the fanner basket&rsquo;s name in Choctaw. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","tp":"mcq"},"e2fa4379-f216-4286-8c00-6098b985ceea":{"r":"<p style=\"text-align: left;\">Choice D is correct. It's given that triangle <math alttext=\"upper A upper B upper C\"><mrow>\n<mi>A</mi>\n<mi>B</mi>\n<mi>C</mi>\n</mrow>\n</math> is similar to triangle <math alttext=\"upper X upper Y upper Z\"><mrow>\n<mi>X</mi>\n<mi>Y</mi>\n<mi>Z</mi>\n</mrow>\n</math>, where <math alttext=\"upper A\"><mi>A</mi>\n</math>, <math alttext=\"upper B\"><mi>B</mi>\n</math>, and <math alttext=\"upper C\"><mi>C</mi>\n</math> correspond to <math alttext=\"upper X\"><mi>X</mi>\n</math>, <math alttext=\"upper Y\"><mi>Y</mi>\n</math>, and <math alttext=\"upper Z\"><mi>Z</mi>\n</math>, respectively. It follows that side <math alttext=\"upper A upper B\"><mrow>\n<mi>A</mi>\n<mi>B</mi>\n</mrow>\n</math> corresponds to side <math alttext=\"upper X upper Y\"><mrow>\n<mi>X</mi>\n<mi>Y</mi>\n</mrow>\n</math> and side <math alttext=\"upper B upper C\"><mrow>\n<mi>B</mi>\n<mi>C</mi>\n</mrow>\n</math> corresponds to side <math alttext=\"upper Y upper Z\"><mrow>\n<mi>Y</mi>\n<mi>Z</mi>\n</mrow>\n</math>. Since the lengths of corresponding sides in similar triangles are proportional, it follows that <math alttext=\"StartFraction upper X upper Y Over upper A upper B EndFraction equals StartFraction upper Y upper Z Over upper B upper C EndFraction\"><mfrac><mrow><mi>X</mi><mi>Y</mi></mrow><mrow><mi>A</mi><mi>B</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>Y</mi><mi>Z</mi></mrow><mrow><mi>B</mi><mi>C</mi></mrow></mfrac></math>. Substituting <math alttext=\"170\"><mn>170</mn>\n</math> for <math alttext=\"upper A upper B\"><mrow>\n<mi>A</mi>\n<mi>B</mi>\n</mrow>\n</math>, <math alttext=\"60\"><mn>60</mn>\n</math> for <math alttext=\"upper Y upper Z\"><mrow>\n<mi>Y</mi>\n<mi>Z</mi>\n</mrow>\n</math>, and <math alttext=\"850\"><mn>850</mn>\n</math> for <math alttext=\"upper B upper C\"><mrow>\n<mi>B</mi>\n<mi>C</mi>\n</mrow>\n</math> in this equation yields <math alttext=\"StartFraction upper X upper Y Over 170 EndFraction equals StartFraction 60 Over 850 EndFraction\"><mfrac><mrow><mi>X</mi><mi>Y</mi></mrow><mn>170</mn></mfrac><mo>=</mo><mfrac><mn>60</mn><mn>850</mn></mfrac></math>. Multiplying each side of this equation by <math alttext=\"170\"><mn>170</mn>\n</math> yields <math alttext=\"upper X upper Y equals 12\"><mrow>\n<mrow>\n<mi>X</mi>\n<mi>Y</mi>\n</mrow>\n<mo>=</mo>\n<mn>12</mn>\n</mrow>\n</math>. Therefore, the length of&nbsp;<math alttext=\"line segment upper X upper Y\"><mover><mrow><mi>X</mi><mi>Y</mi></mrow><mo>&macr;</mo></mover></math> is <math alttext=\"12\"><mn>12</mn>\n</math>.</p>\n<p style=\"text-align: left;\">Choice A is incorrect and may result from conceptual or calculation errors.</p>\n<p style=\"text-align: left;\">Choice B is incorrect and may result from conceptual or calculation errors.</p>\n<p style=\"text-align: left;\">Choice C is incorrect. This is the length of <math alttext=\"line segment upper Y upper Z\"><mover><mrow><mi>Y</mi><mi>Z</mi></mrow><mo>&macr;</mo></mover></math>, not <math alttext=\"line segment upper X upper Y\"><mover><mrow><mi>X</mi><mi>Y</mi></mrow><mo>&macr;</mo></mover></math>.</p>","st":"","tp":"mcq","a":"D","o":["<p><math alttext=\"204\"><mn>204</mn>\n</math></p>","<p><math alttext=\"182\"><mn>182</mn>\n</math></p>","<p><math alttext=\"60\"><mn>60</mn>\n</math></p>","<p><math alttext=\"12\"><mn>12</mn>\n</math></p>"],"q":"<p style=\"text-align: left;\">Triangle <math alttext=\"upper A upper B upper C\"><mrow>\n\t<mi>A</mi>\n\t<mi>B</mi>\n\t<mi>C</mi>\n</mrow>\n</math> is similar to triangle <math alttext=\"upper X upper Y upper Z\"><mrow>\n\t<mi>X</mi>\n\t<mi>Y</mi>\n\t<mi>Z</mi>\n</mrow>\n</math>, where <math alttext=\"upper A\"><mi>A</mi>\n</math>, <math alttext=\"upper B\"><mi>B</mi>\n</math>, and <math alttext=\"upper C\"><mi>C</mi>\n</math> correspond to <math alttext=\"upper X\"><mi>X</mi>\n</math>, <math alttext=\"upper Y\"><mi>Y</mi>\n</math>, and <math alttext=\"upper Z\"><mi>Z</mi>\n</math>, respectively. In triangle <math alttext=\"upper A upper B upper C\"><mrow>\n\t<mi>A</mi>\n\t<mi>B</mi>\n\t<mi>C</mi>\n</mrow>\n</math>, the length of <math alttext=\"line segment upper A upper B\"><mover><mrow><mi>A</mi><mi>B</mi></mrow><mo>&#175;</mo></mover></math> is <math alttext=\"170\"><mn>170</mn>\n</math> and the length of <math alttext=\"line segment upper B upper C\"><mover><mrow><mi>B</mi><mi>C</mi></mrow><mo>&#175;</mo></mover></math> is <math alttext=\"850\"><mn>850</mn>\n</math>. In triangle <math alttext=\"upper X upper Y upper Z\"><mrow>\n\t<mi>X</mi>\n\t<mi>Y</mi>\n\t<mi>Z</mi>\n</mrow>\n</math>, the length of <math alttext=\"line segment upper Y upper Z\"><mover><mrow><mi>Y</mi><mi>Z</mi></mrow><mo>&#175;</mo></mover></math> is <math alttext=\"60\"><mn>60</mn>\n</math>. What is the length of <math alttext=\"line segment upper X upper Y\"><mover><mrow><mi>X</mi><mi>Y</mi></mrow><mo>&#175;</mo></mover></math>?</p>"}});
